```java
// ─── File: src/main/java/com/bank/marker/model/Trade.java ───
package com.bank.marker.model;

import java.math.BigDecimal;

public class Trade implements Cloneable {
    private String tradeId;
    private String symbol;
    private BigDecimal amount;

    public Trade(String tradeId, String symbol, BigDecimal amount) {
        this.tradeId = tradeId;
        this.symbol = symbol;
        this.amount = amount;
    }

    // Cloneable marker allows clone():
    @Override
    public Trade clone() {
        try {
            return (Trade) super.clone();  // shallow clone — OK for immutable fields
        } catch (CloneNotSupportedException e) {
            throw new AssertionError("Implements Cloneable — should never happen");
        }
    }

    // Better alternative: copy constructor
    public Trade(Trade source) {
        this.tradeId = source.tradeId + "-COPY";
        this.symbol = source.symbol;
        this.amount = source.amount;
    }

    public String getTradeId() { return tradeId; }
    public String getSymbol() { return symbol; }
    public BigDecimal getAmount() { return amount; }
    public void setAmount(BigDecimal amount) { this.amount = amount; }
}
