```java
// ─── File: src/test/java/com/bank/marker/MarkerInterfaceTest.java ───
package com.bank.marker;

import com.bank.marker.model.*;
import com.bank.marker.service.TransferService;
import org.junit.jupiter.api.Test;
import java.io.*;
import java.math.BigDecimal;
import static org.assertj.core.api.Assertions.*;

class MarkerInterfaceTest {

    // ═══ SERIALIZABLE: write/read to byte stream ═══
    @Test
    void serializable_canSerializeAndDeserialize() throws Exception {
        Account original = new Account("SAV2001", new BigDecimal("125000"));

        // Serialize:
        ByteArrayOutputStream bos = new ByteArrayOutputStream();
        new ObjectOutputStream(bos).writeObject(original);

        // Deserialize:
        ByteArrayInputStream bis = new ByteArrayInputStream(bos.toByteArray());
        Account restored = (Account) new ObjectInputStream(bis).readObject();

        assertThat(restored.getAccountId()).isEqualTo("SAV2001");
        assertThat(restored.getBalance()).isEqualByComparingTo("125000");
        assertThat(restored).isNotSameAs(original);  // different object in memory!
    }

    @Test
    void serializable_withoutMarkerThrowsException() {
        // A class NOT implementing Serializable:
        record NonSerializable(String data) {}

        assertThatThrownBy(() -> {
            new ObjectOutputStream(new ByteArrayOutputStream())
                .writeObject(new NonSerializable("test"));
        }).isInstanceOf(NotSerializableException.class);
        // Without Serializable marker → NotSerializableException!
    }

    // ═══ CLONEABLE: clone() works ═══
    @Test
    void cloneable_cloneCreatesShallowCopy() {
        Trade original = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        Trade cloned = original.clone();

        assertThat(cloned.getTradeId()).isEqualTo(original.getTradeId());
        assertThat(cloned).isNotSameAs(original);  // different object!
    }

    @Test
    void cloneable_copyConstructorIsBetter() {
        Trade original = new Trade("TRD-001", "RELIANCE", new BigDecimal("245050"));
        Trade copied = new Trade(original);  // copy constructor — cleaner!

        assertThat(copied.getTradeId()).isEqualTo("TRD-001-COPY");  // customized ID
        assertThat(copied.getSymbol()).isEqualTo("RELIANCE");
    }

    // ═══ CUSTOM MARKER: InternationalTransferCapable ═══
    @Test
    void customMarker_nriCanTransferInternationally() {
        TransferService service = new TransferService();
        NRIAccount nri = new NRIAccount("NRI001", new BigDecimal("2500000"), "USD");

        String result = service.transferInternational(nri, new BigDecimal("50000"), "USA");
        assertThat(result).contains("International transfer").contains("USA");
    }

    @Test
    void customMarker_savingsCannotTransferInternationally() {
        TransferService service = new TransferService();
        Account savings = new Account("SAV001", new BigDecimal("125000"));

        assertThatThrownBy(() -> service.transferInternational(savings, new BigDecimal("50000"), "USA"))
            .isInstanceOf(UnsupportedOperationException.class)
            .hasMessageContaining("cannot do international");
        // Account doesn't implement InternationalTransferCapable → blocked!
    }

    // ═══ MARKER IS A TYPE — can be used in generics ═══
    @Test
    void markerAsType() {
        Account nri = new NRIAccount("NRI001", new BigDecimal("2500000"), "USD");
        assertThat(nri).isInstanceOf(Serializable.class);                 // from Account
        assertThat(nri).isInstanceOf(InternationalTransferCapable.class); // from NRIAccount
        // Marker interfaces ARE types — can be used in instanceof, generics, variable declarations
    }
}
```
